const std = @import("std");

fn factorial(n: u64) u64 {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

pub fn main() !void {
    const stdout = std.io.getStdOut().writer();
    var total: usize = 0;
    for (1..101) |i| {
        if (i % 3 == 0) continue;
        total += i;
    }
    try stdout.print("total={d}, 5!={d}\n", .{ total, factorial(5) });

    var i: usize = 0;
    while (i < 3) : (i += 1) {
        try stdout.print("i={d} ", .{i});
    }
    try stdout.print("\n", .{});
}

