fn maxOf(comptime T: type, a: T, b: T) T {
    return if (a > b) a else b;
}

fn Box(comptime T: type) type {
    return struct {
        value: T,
        const Self = @This();
        fn get(self: Self) T {
            return self.value;
        }
    };
}

