const std = @import("std");

fn worker(id: usize, out: *std.atomic.Value(u64)) void {
    out.fetchAdd(@intCast(id * 10), .SeqCst);
}

pub fn main() !void {
    var counter = std.atomic.Value(u64).init(0);
    var threads: [4]std.Thread = undefined;
    for (&threads, 0..) |*t, i| {
        t.* = try std.Thread.spawn(.{}, worker, .{ i + 1, &counter });
    }
    for (&threads) |*t| t.join();
    try std.io.getStdOut().writer().print("总和={d}\n", .{counter.load(.SeqCst)});
    // 0.11 起 async/await 关键字被移除，异步由库或线程实现
}

