const std = @import("std");

fn parsePort(s: []const u8) !u16 {
    if (s.len == 0 or s.len > 5) return error.InvalidPort;
    for (s) |ch| {
        if (!std.ascii.isDigit(ch)) return error.InvalidPort;
    }
    const p = std.fmt.parseInt(u16, s, 10) catch return error.InvalidPort;
    if (p == 0) return error.InvalidPort;
    return p;
}

pub fn main() !void {
    const stdout = std.io.getStdOut().writer();
    try stdout.print("端口={d}\n", .{try parsePort("8080")});
    if (parsePort("80; rm -rf /")) |_| {} else |err| {
        try stdout.print("拒绝非法输入: {s}\n", .{@errorName(err)});
    }

    const key: []const u8 = std.process.getEnvVarOwned(std.heap.page_allocator, "APP_KEY") catch "";
    try stdout.print("密钥长度={d}\n", .{key.len});
}

const std = @import("std");

pub fn main() !void {
    const allocator = std.heap.page_allocator;
    const args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    if (args.len < 2) {
        try std.io.getStdErr().writer().print("用法: {s} <文件...>\n", .{args[0]});
        std.process.exit(1);
    }
    var total: usize = 0;
    for (args[1..]) |path| {
        const content = std.fs.cwd().readFileAlloc(allocator, path, 8 << 20) catch {
            try std.io.getStdErr().writer().print("无法读取 {s}\n", .{path});
            continue;
        };
        defer allocator.free(content);
        const lines = std.mem.count(u8, content, "\n") + 1;
        total += lines;
        try std.io.getStdOut().writer().print("{d:>6} {s}\n", .{ lines, path });
    }
    try std.io.getStdOut().writer().print("{d:>6} 总计\n", .{total});
}

const std = @import("std");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    const stdout = std.io.getStdOut().writer();
    const raw = "小明,研发,18000\n小红,研发,22000\n小刚,市场,15000\n";
    var totals = std.StringHashMap(u64).init(allocator);
    defer totals.deinit();
    var lines = std.mem.tokenizeAny(u8, raw, "\n");
    while (lines.next()) |line| {
        var it = std.mem.split(u8, line, ",");
        _ = it.next() orelse continue;
        const dept = it.next() orelse continue;
        const salary = std.fmt.parseInt(u64, it.next() orelse continue, 10) catch continue;
        const entry = try totals.getOrPut(dept);
        if (!entry.found_existing) entry.value_ptr.* = 0;
        entry.value_ptr.* += salary;
    }
    var iter = totals.iterator();
    while (iter.next()) |e| {
        try stdout.print("{s} 总薪资={d}\n", .{ e.key_ptr.*, e.value_ptr.* });
    }
}

