const std = @import("std");

const Buffer = struct {
    data: []u8,
    allocator: std.mem.Allocator,

    fn init(allocator: std.mem.Allocator, n: usize) !Buffer {
        return .{ .data = try allocator.alloc(u8, n), .allocator = allocator };
    }

    fn deinit(self: *Buffer) void {
        self.allocator.free(self.data);
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    var buf = try Buffer.init(gpa.allocator(), 16);
    defer buf.deinit();
    @memset(buf.data, 0);
    try std.io.getStdOut().writer().print("容量={d}\n", .{buf.data.len});
}

